"""Package the ChatGPT skills-only plugin generated by .github/generate.py.

The package carries no connection: each user registers the Momonga MCP connection in their own account.
Usage: python3 .github/package-chatgpt.py OUTPUT_ZIP
"""
import json
from pathlib import Path
import runpy
import sys
import zipfile

ROOT = Path(__file__).resolve().parent.parent
generate = runpy.run_path(str(ROOT / '.github/generate.py'))


def package(root, output):
    source = root / generate['CHATGPT']
    if output.resolve().is_relative_to(source.resolve()):
        raise ValueError('Output must be outside the generated plugin')
    expected = generate['generated'](root)
    names = sorted(name.removeprefix(generate['CHATGPT'] + '/') for name in expected if name.startswith(generate['CHATGPT'] + '/'))
    present = sorted(str(path.relative_to(source)) for path in source.rglob('*') if path.is_file())
    if present != names:
        raise ValueError('The ChatGPT plugin must contain only its manifest and generated skills')
    for name in names:
        if (source / name).read_text() != expected[f"{generate['CHATGPT']}/{name}"]:
            raise ValueError(f'{name}: out of date; run python3 .github/generate.py')
    manifest = json.loads((source / '.codex-plugin/plugin.json').read_text())
    if {'apps', 'mcpServers'} & manifest.keys() or manifest['skills'] != './skills/':
        raise ValueError('The ChatGPT plugin must be skills-only')
    if sum(name.endswith('/SKILL.md') for name in names) != 24:
        raise ValueError('Expected 24 command skills')
    with zipfile.ZipFile(output, 'w', zipfile.ZIP_DEFLATED) as archive:
        for name in names:
            archive.writestr(name, (source / name).read_bytes())
    return manifest['name'], manifest['version']


if __name__ == '__main__':
    if len(sys.argv) != 2:
        sys.exit(__doc__)
    try:
        name, version = package(ROOT, Path(sys.argv[1]))
        print(f'{name}: version {version}, 24 skills -> {sys.argv[1]}')
    except (ValueError, KeyError, OSError) as error:
        sys.exit(str(error))
